CREATE OR REPLACE FUNCTION public.get_contact_statistics(p_contact_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$ DECLARE result jsonb; total_interactions int; total_deals int; total_meetings int; total_proposals int; total_tasks int; last_interaction_at timestamp with time zone; BEGIN SELECT count(*) INTO total_interactions FROM interactions WHERE contact_id = p_contact_id; SELECT count(*) INTO total_deals FROM interactions WHERE contact_id = p_contact_id AND type IN ('deal','sale'); SELECT count(*) INTO total_meetings FROM interactions WHERE contact_id = p_contact_id AND type IN ('meeting','reuniao'); SELECT count(*) INTO total_proposals FROM interactions WHERE contact_id = p_contact_id AND type IN ('proposal','proposta'); SELECT count(*) INTO total_tasks FROM interactions WHERE contact_id = p_contact_id AND type IN ('task','tarefa'); SELECT MAX(data_interacao) INTO last_interaction_at FROM interactions WHERE contact_id = p_contact_id; SELECT jsonb_build_object( 'total_interactions', total_interactions, 'total_deals', total_deals, 'total_meetings', total_meetings, 'total_proposals', total_proposals, 'total_tasks', total_tasks, 'open_deals_value', 0, 'won_deals_value', 0, 'avg_response_time_hours', NULL, 'last_interaction_at', last_interaction_at, 'days_since_last_contact', CASE WHEN last_interaction_at IS NULL THEN NULL ELSE EXTRACT(DAY FROM now() - last_interaction_at)::int END, 'nps_score', NULL, 'churn_risk', NULL ) INTO result; RETURN result; END; $function$
